/* MODULE dl08 · Bước 7 Đo lường · Chỉ số phù phiếm và chỉ số ra quyết định
   10 bài × 7 câu. Mỗi bài đi vào một cặp chỉ số cụ thể. Mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'dl08', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:dl08-01', skill:'measure', read:'6 phút', t:'Fanpage tăng 20.000 follower, sao đơn hàng vẫn đứng yên?',
  situation:'Một tiệm bánh ngọt ở Đà Nẵng chạy minigame "like, share, tag 3 bạn" trong hai tuần. Fanpage từ 5.000 lên 25.000 follower, chủ tiệm rất vui. Nhưng số đơn đặt bánh qua inbox mỗi tuần vẫn quanh 60 đơn, như trước minigame. Chủ tiệm hỏi bạn: có nên chạy thêm một đợt minigame nữa không?',
  concept:{ name:'Follower và người mua là hai tập người khác nhau',
    body:'Follower chỉ cho biết bao nhiêu người từng bấm theo dõi. Người mua mới là người trả tiền. Hai tập này chỉ chồng lên nhau một phần, và cách bạn kéo follower quyết định phần chồng lên to hay nhỏ. Minigame tặng quà kéo người thích quà, không nhất thiết là người ở gần và muốn mua bánh. Chỉ số ra quyết định ở đây là <b>số người mua mới đến từ fanpage</b> hoặc <b>tỉ lệ follower mới trở thành người mua</b>. Nếu con số này không nhúc nhích, thêm follower không làm tiệm khá lên.' },
  example:'Tiệm đếm lại: trong 20.000 follower mới, chỉ 30 người từng nhắn tin hỏi giá và 12 người đặt bánh. Tỉ lệ follower mới thành người mua là 12 ÷ 20.000 = 0,06%. Ngược lại, 5.000 follower cũ (phần lớn là khách quen trong quận) đem về khoảng 60 đơn mỗi tuần. Tiệm dừng minigame, chuyển tiền sang quảng cáo nhắm bán kính 5 km quanh tiệm kèm mã giảm cho đơn đầu, và đo bằng số đơn có mã.',
  takeaway:'Follower là số người đứng xem; hãy đo số người bước vào mua.',
  apply:'Mở fanpage của bạn: trong 100 người theo dõi mới nhất, bấm vào hồ sơ từng người và đánh dấu ai có vẻ là khách mục tiêu thật.',
  mistakes:['Coi tăng follower là bằng chứng chiến dịch thành công.','Chạy minigame tặng quà đại trà rồi ngạc nhiên vì follower không mua.'],
  q:[
  { type:'mcq', stem:'Đoán trước: fanpage tiệm bánh tăng từ 5.000 lên 25.000 follower sau minigame. Số đơn mỗi tuần nhiều khả năng sẽ ra sao?',
    options:[{k:'a',t:'Tăng gấp năm lần theo đúng tỉ lệ tăng của số follower'},{k:'b',t:'Tăng mạnh nhưng chậm vài tháng, vì follower mới cần thời gian làm quen rồi mới mua'},
             {k:'c',t:'Gần như đứng yên, vì người đến vì quà ít khi là khách mua bánh'},{k:'d',t:'Giảm đi, vì follower nhiều làm bài đăng bị Facebook hạn chế phân phối'}],
    answer:'c', why:{a:'Đơn chỉ tăng theo follower nếu follower mới giống follower cũ; người đến vì quà thì không giống.',
      b:'Có vài người mua muộn, nhưng phần lớn người săn quà ở xa hoặc không có nhu cầu, nên không có "đợt tăng muộn" đáng kể.',
      c:'Đúng. Minigame kéo người thích quà; phần chồng lên với khách mua bánh rất nhỏ.',
      d:'Không có cơ chế nào làm đơn giảm chỉ vì follower tăng; vấn đề là đơn không tăng.'} },
  { type:'mcq', stem:'Chủ tiệm hỏi có nên chạy thêm một đợt minigame. Bạn đề xuất gì?',
    options:[{k:'a',t:'Chạy tiếp nhưng tăng giá trị quà để kéo được nhiều follower hơn nữa'},{k:'b',t:'Dừng minigame, chuyển tiền sang kéo khách quanh tiệm và đo bằng số đơn mới'},
             {k:'c',t:'Chạy tiếp, vì follower đông thì sau này mỗi bài đăng bán hàng sẽ tiếp cận được nhiều người hơn'},{k:'d',t:'Xoá bớt follower ảo để fanpage trông thật hơn, rồi mới chạy đợt mới'}],
    answer:'b', why:{a:'Quà to hơn kéo thêm người săn quà, càng xa tập khách mua.',
      b:'Đúng. Chọn cách kéo người có thể mua, và chọn thước đo là đơn hàng mới thay vì follower.',
      c:'Đăng bài cho người không có nhu cầu thì vẫn không ra đơn; số follower không tự đổi thành sức mua.',
      d:'Dọn follower không giải quyết việc gì: vấn đề là chọn sai thước đo, không phải con số trông kém thật.'} },
  { type:'calc', stem:'Minigame kéo 20.000 follower mới, trong đó 12 người đặt bánh. Tỉ lệ follower mới trở thành người mua là bao nhiêu phần trăm?',
    unit:'%', ans:0.06, tol:0.001, wrong:[[0.24,'SAI_MAU_SO'],[0.048,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ = số người mua trong nhóm ÷ số người của nhóm đó.','Mẫu số là 20.000 follower mới, không phải 5.000 hay 25.000.','12 ÷ 20.000 = 0,0006 = <b>0,06%</b>.'] },
  { type:'mcq', stem:'Một quán cà phê khoe "fanpage 50.000 follower" khi xin vay vốn. Người cho vay nên hỏi thêm con số nào?',
    options:[{k:'a',t:'Tỉ lệ tương tác trung bình trên mỗi bài đăng của fanpage'},{k:'b',t:'Số follower tăng thêm mỗi tháng trong 6 tháng gần nhất, để thấy đà phát triển'},
             {k:'c',t:'Số lượt chia sẻ bài viết, vì chia sẻ thể hiện mức độ yêu thích'},{k:'d',t:'Doanh thu mỗi tháng và bao nhiêu phần đến từ khách biết qua fanpage'}],
    answer:'d', why:{a:'Tương tác gần với sở thích hơn follower, nhưng vẫn chưa phải tiền.',
      b:'Tốc độ tăng follower vẫn là follower; nó không nói quán thu được bao nhiêu.',
      c:'Chia sẻ là thiện cảm, không phải khả năng trả nợ.',
      d:'Đúng. Khoản vay được trả bằng doanh thu; câu hỏi là fanpage đóng góp bao nhiêu vào doanh thu đó.'} },
  { type:'mcq', stem:'Khi nào số follower có thể là chỉ số đáng theo dõi?',
    options:[{k:'a',t:'Khi fanpage vượt mốc 10.000 và được Facebook cấp tích xanh'},{k:'b',t:'Khi đã chứng minh follower mới mua theo một tỉ lệ khá ổn định'},
             {k:'c',t:'Khi đối thủ có nhiều follower hơn và bạn cần đuổi kịp cho bằng'},{k:'d',t:'Khi ngân sách còn dư và chưa biết nên chi tiêu vào việc gì khác'}],
    answer:'b', why:{a:'Mốc hay dấu tích không làm follower mua nhiều hơn.',
      b:'Đúng. Khi đã biết follower đổi ra đơn theo tỉ lệ nào, follower mới thành chỉ báo sớm cho doanh thu.',
      c:'Đua số follower với đối thủ là đua trên thước đo không gắn với tiền.',
      d:'Ngân sách dư không biến một chỉ số phù phiếm thành chỉ số ra quyết định.'} },
  { type:'mcq', stem:'Shop quần áo A có 8.000 follower, shop B có 80.000. Tháng này A bán 400 đơn, B bán 350 đơn. Nhận định nào đúng?',
    options:[{k:'a',t:'B mạnh hơn vì có tệp khách tiềm năng lớn gấp mười lần shop A'},{k:'b',t:'A chỉ ăn may trong tháng này, lâu dài B sẽ vượt nhờ số follower đông'},
             {k:'c',t:'A đổi người theo dõi thành người mua tốt hơn B rất nhiều'},{k:'d',t:'Hai shop gần như ngang nhau nên chưa thể rút ra nhận định nào'}],
    answer:'c', why:{a:'Follower không phải tệp khách tiềm năng nếu họ không mua; kết quả cho thấy điều đó.',
      b:'Không có cơ sở cho "ăn may"; follower đông mà ít đơn là dấu hiệu tệp kém chất lượng.',
      c:'Đúng. 400 đơn trên 8.000 follower so với 350 trên 80.000 là khác biệt rất lớn về chất lượng tệp.',
      d:'Đơn gần bằng nhau nhưng follower chênh mười lần, đó chính là thông tin cần đọc.'} },
  { type:'mcq', stem:'Sếp đặt KPI quý cho bạn là "fanpage đạt 100.000 follower". Bạn nên phản hồi thế nào?',
    options:[{k:'a',t:'Nhận KPI và chạy quảng cáo lượt thích trang giá rẻ cho nhanh đạt'},{k:'b',t:'Từ chối KPI vì mạng xã hội không đo được hiệu quả kinh doanh'},
             {k:'c',t:'Nhận KPI nhưng lén đo thêm doanh thu, không cần báo sếp chuyện này'},{k:'d',t:'Đề xuất thêm KPI số đơn từ fanpage, follower chỉ là số tham khảo'}],
    answer:'d', why:{a:'Đạt số bằng lượt thích giá rẻ là tối ưu đúng cái sai; sếp sẽ hỏi vì sao không ra tiền.',
      b:'Mạng xã hội đo được hiệu quả, chỉ cần chọn đúng chỉ số.',
      c:'Đo mà không thống nhất với sếp thì cuối quý hai bên vẫn chấm theo follower.',
      d:'Đúng. Gắn KPI vào kết quả kinh doanh và giữ follower ở vai trò phụ.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:dl08-02', skill:'measure', read:'6 phút', t:'Video 1 triệu view, nhưng bao nhiêu người xem tới đoạn nói về sản phẩm?',
  situation:'Một thương hiệu nước mắm đặt KOC làm video TikTok 45 giây. Video đạt 1 triệu lượt xem, cả nhóm ăn mừng. Sản phẩm chỉ xuất hiện ở giây thứ 30, khi KOC nêm nước mắm vào món kho. Báo cáo của TikTok cho thấy chỉ 8% người xem tới giây 30. Tuần sau nhóm phải quyết định có đặt thêm 5 video cùng kiểu không.',
  concept:{ name:'Lượt xem khác lượt xem tới đoạn quan trọng',
    body:'Trên TikTok hay Reels, một lượt xem được đếm rất sớm, có khi chỉ vài giây. Người lướt qua cũng tính là một view. Điều bạn cần biết là bao nhiêu người <b>xem tới đoạn có thông điệp</b>: đoạn sản phẩm xuất hiện, đoạn nói giá, đoạn kêu gọi hành động. Hãy đọc biểu đồ giữ chân khán giả (retention) và lấy số người còn lại tại đúng giây đó. Con số này mới quyết định bạn có nên làm thêm video kiểu đó, hay phải đưa sản phẩm lên sớm hơn.' },
  example:'1.000.000 view × 8% = 80.000 người thấy nước mắm được nêm vào món. Một video khác chỉ 300.000 view nhưng sản phẩm xuất hiện ngay giây thứ 3, khi 60% người xem còn ở lại: 300.000 × 60% = 180.000 người thấy sản phẩm. Video ít view hơn lại đưa thông điệp tới gấp hơn hai lần số người. Nhóm quyết định đặt thêm video, nhưng yêu cầu sản phẩm xuất hiện trong 5 giây đầu.',
  takeaway:'Đừng đếm người đi ngang; đếm người còn ở lại khi sản phẩm xuất hiện.',
  apply:'Mở báo cáo một video của bạn, tìm giây sản phẩm xuất hiện, ghi lại tỉ lệ người xem còn lại ở giây đó.',
  mistakes:['So video bằng tổng view mà không nhìn biểu đồ giữ chân.','Để sản phẩm xuất hiện ở cuối video vì sợ "lộ quảng cáo".'],
  q:[
  { type:'mcq', stem:'Đoán trước: một video 1 triệu view, sản phẩm xuất hiện ở giây 30. Bao nhiêu người thực sự thấy sản phẩm?',
    options:[{k:'a',t:'Có thể chỉ vài chục nghìn, vì đa số lướt đi trước giây 30'},{k:'b',t:'Khoảng 1 triệu người, vì mỗi lượt xem là một người đã thấy video'},
             {k:'c',t:'Khoảng một nửa, vì người xem thường ở lại tới giữa mỗi video ngắn'},{k:'d',t:'Không đo được, vì nền tảng không cho biết người xem tới giây nào'}],
    answer:'a', why:{a:'Đúng. Video ngắn mất người rất nhanh; tới giây 30 thường chỉ còn một phần nhỏ.',
      b:'Lượt xem được đếm từ vài giây đầu; người lướt qua cũng là một view.',
      c:'Không có quy luật "ở lại một nửa"; phải đọc số thật trên biểu đồ.',
      d:'TikTok, Reels và YouTube đều có biểu đồ giữ chân theo từng giây.'} },
  { type:'mcq', stem:'Nhóm sắp đặt thêm 5 video cùng kiểu. Bạn sửa gì trong brief trước khi đặt?',
    options:[{k:'a',t:'Yêu cầu KOC cam kết mỗi video đạt tối thiểu 1 triệu lượt xem'},{k:'b',t:'Kéo dài video lên 90 giây để có thêm thời gian kể về sản phẩm'},
             {k:'c',t:'Đưa sản phẩm vào 5 giây đầu và đo người còn xem tại đoạn đó'},{k:'d',t:'Giữ nguyên kịch bản cũ vì kiểu video này đã chứng minh được là viral'}],
    answer:'c', why:{a:'Cam kết view chỉ ép KOC tối ưu đúng cái số phù phiếm.',
      b:'Video dài hơn thì càng ít người ở lại tới đoạn sản phẩm.',
      c:'Đúng. Đổi vị trí thông điệp và đổi thước đo sang người thấy sản phẩm.',
      d:'Viral về view không có nghĩa là viral về thông điệp; 92% người không thấy sản phẩm.'} },
  { type:'calc', stem:'Video B có 300.000 view; tại giây thứ 3, lúc sản phẩm xuất hiện, còn 60% người xem. Bao nhiêu người thấy sản phẩm?',
    unit:'người', ans:180000, tol:1, wrong:[[300000,'QUEN_TI_LE_CHUYEN_DOI'],[5000,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Người thấy sản phẩm = số view × tỉ lệ còn xem tại giây đó.','300.000 × 60% = <b>180.000</b> người.'] },
  { type:'mcq', stem:'Video A 1 triệu view, 8% xem tới sản phẩm. Video B 300.000 view, 60% xem tới sản phẩm. Kết luận nào đúng?',
    options:[{k:'a',t:'A tốt hơn vì tổng view lớn hơn B tới hơn ba lần'},{k:'b',t:'B đưa sản phẩm tới nhiều người hơn A, dù có ít view hơn hẳn'},
             {k:'c',t:'Hai video ngang nhau vì cùng một KOC, cùng một sản phẩm'},{k:'d',t:'Không so được vì hai video có độ dài khác nhau hoàn toàn'}],
    answer:'b', why:{a:'80.000 người thấy sản phẩm ở A, 180.000 ở B; view tổng che mất điều này.',
      b:'Đúng. So bằng số người thấy thông điệp, B hơn A hơn hai lần.',
      c:'Cùng KOC nhưng khác cấu trúc video, kết quả khác xa nhau.',
      d:'So được, vì ta so cùng một đại lượng: số người thấy sản phẩm.'} },
  { type:'mcq', stem:'Một video có tỉ lệ xem hết 70% nhưng chỉ 20.000 view. Điều này gợi ý gì?',
    options:[{k:'a',t:'Video kém vì ít view, nên bỏ kiểu nội dung này đi ngay'},{k:'b',t:'Tỉ lệ xem hết cao là do video quá ngắn nên không có ý nghĩa gì'},
             {k:'c',t:'Nội dung giữ người tốt; nên thử tăng phân phối cho nó'},{k:'d',t:'Cần thêm hashtag trending để view tăng lên cho bằng các video khác'}],
    answer:'c', why:{a:'Ít view có thể do phân phối, không phải do nội dung; người xem thì ở lại rất tốt.',
      b:'Video ngắn dễ xem hết hơn, nhưng 70% vẫn là tín hiệu nên so với video cùng độ dài.',
      c:'Đúng. Nội dung đã chứng minh giữ được người; phần yếu là độ phủ, có thể mua thêm.',
      d:'Hashtag trending kéo người đi ngang, có thể làm tỉ lệ xem hết giảm.'} },
  { type:'mcq', stem:'Với video quảng cáo có kêu gọi "bấm vào giỏ hàng" ở giây 20, chỉ số nào nên đặt lên đầu báo cáo?',
    options:[{k:'a',t:'Tổng số lượt xem video trong 7 ngày đầu tiên sau khi đăng'},{k:'b',t:'Số lượt thích và bình luận, vì thể hiện độ yêu thích nội dung'},
             {k:'c',t:'Thời gian xem trung bình của toàn bộ người đã bấm vào xem'},{k:'d',t:'Người còn xem ở giây 20 và số lượt bấm vào giỏ hàng'}],
    answer:'d', why:{a:'Tổng view không cho biết ai nghe được lời kêu gọi.',
      b:'Thích và bình luận là phản ứng với nội dung, không phải hành động mua.',
      c:'Thời gian xem trung bình bị kéo bởi cả người xem rất lâu lẫn rất ngắn; nó không trả lời "bao nhiêu người tới giây 20".',
      d:'Đúng. Hai con số này nối trực tiếp thông điệp với hành động bạn muốn.'} },
  { type:'mcq', stem:'Agency báo cáo "chi phí mỗi lượt xem chỉ 30 đồng, rẻ nhất ngành". Bạn nên hỏi lại điều gì?',
    options:[{k:'a',t:'Chi phí cho mỗi người xem tới đoạn sản phẩm là bao nhiêu'},{k:'b',t:'Có thể giảm giá mỗi lượt xem xuống 20 đồng được hay không'},
             {k:'c',t:'Đối thủ đang trả bao nhiêu cho mỗi lượt xem cùng loại này'},{k:'d',t:'Tổng số lượt xem đạt được đã vượt mục tiêu ban đầu bao nhiêu'}],
    answer:'a', why:{a:'Đúng. View rẻ có thể là view lướt; hãy tính giá trên mỗi người thực sự thấy thông điệp.',
      b:'Ép giá view xuống càng đẩy agency mua view kém chất lượng hơn.',
      c:'So giá view với đối thủ vẫn là so trên thước đo phù phiếm.',
      d:'Vượt mục tiêu view không nói gì về thông điệp.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:dl08-03', skill:'measure', read:'7 phút', t:'App đạt 100.000 lượt tải, vậy có bao nhiêu người thật sự dùng?',
  situation:'Một ứng dụng đặt lịch cắt tóc ở TP.HCM chạy chiến dịch tặng 50.000đ cho người tải app. Sau một tháng, app đạt 100.000 lượt tải và nhóm định báo cáo với nhà đầu tư. Nhưng số lịch hẹn đặt qua app mỗi tuần chỉ khoảng 1.500. Nhà đầu tư hỏi: "Bao nhiêu người còn dùng app sau 30 ngày?"',
  concept:{ name:'Lượt tải và người dùng hoạt động',
    body:'Lượt tải chỉ đếm lần cài đặt. Rất nhiều người cài xong, nhận quà rồi xoá, hoặc không bao giờ mở lại. Chỉ số ra quyết định là <b>người dùng hoạt động</b>: số người thực hiện hành động cốt lõi (ở đây là đặt lịch) trong một khoảng thời gian, thường tính theo tuần (WAU) hoặc tháng (MAU). Đi kèm là <b>tỉ lệ giữ chân</b>: trong 100 người tải tháng này, bao nhiêu người còn đặt lịch sau 30 ngày. Nếu tỉ lệ này thấp, mua thêm lượt tải chỉ là đổ nước vào thùng thủng.' },
  example:'Trong 100.000 lượt tải, 40.000 người mở app lần thứ hai, 9.000 người từng đặt ít nhất một lịch, và 4.000 người đặt lịch trong tháng thứ hai. Tỉ lệ người tải còn hoạt động sau 30 ngày: 4.000 ÷ 100.000 = 4%. Chi phí quà là 50.000đ × 100.000 = 5 tỉ đồng, tức 1,25 triệu đồng cho mỗi người dùng còn hoạt động. Nhóm dừng quà cài app, chuyển sang tặng quà sau lịch hẹn đầu tiên hoàn thành.',
  takeaway:'Lượt tải là số người bước qua cửa; người dùng hoạt động là số người ở lại.',
  apply:'Viết ra hành động cốt lõi của sản phẩm bạn, rồi đếm số người làm hành động đó trong 30 ngày qua.',
  mistakes:['Tặng quà cho hành động cài đặt thay vì hành động cốt lõi.','Báo cáo tổng lượt tải cộng dồn như thể là số người dùng hiện tại.'],
  q:[
  { type:'mcq', stem:'Đoán trước: app đạt 100.000 lượt tải nhờ tặng 50.000đ. Sau 30 ngày, số người còn đặt lịch nhiều khả năng là bao nhiêu?',
    options:[{k:'a',t:'Khoảng 70.000 người, vì đã tải về thì phần lớn sẽ dùng thử'},{k:'b',t:'Khoảng 50.000 người, vì một nửa người tải là có nhu cầu thật'},
             {k:'c',t:'Khoảng 100.000 người, vì mỗi lượt tải đều là một người dùng mới'},{k:'d',t:'Chỉ vài nghìn, vì nhiều người tải để nhận quà rồi bỏ app'}],
    answer:'d', why:{a:'Tải về không đồng nghĩa dùng thử; nhiều người không mở lần hai.',
      b:'"Một nửa có nhu cầu" là đoán mò; quà cài app kéo nhiều người không có nhu cầu.',
      c:'Một người có thể tải nhiều lần, và phần lớn không quay lại.',
      d:'Đúng. Quà cho hành động cài đặt kéo người săn quà; số ở lại thường rất thấp.'} },
  { type:'mcq', stem:'Tháng sau còn 5 tỉ ngân sách. Bạn chọn cách chi nào?',
    options:[{k:'a',t:'Tặng quà sau lịch hẹn đầu tiên hoàn thành, đo người còn đặt sau 30 ngày'},{k:'b',t:'Tiếp tục tặng quà cài app vì chi phí mỗi lượt tải đang rất cạnh tranh'},
             {k:'c',t:'Tăng quà lên 100.000đ để đạt 200.000 lượt tải trước khi gọi vốn'},{k:'d',t:'Chuyển toàn bộ tiền sang quảng cáo thương hiệu trên các kênh truyền hình'}],
    answer:'a', why:{a:'Đúng. Thưởng đúng hành động cốt lõi và đo bằng người ở lại.',
      b:'Lượt tải rẻ nhưng người dùng hoạt động rất đắt; rẻ ở chỗ sai.',
      c:'Nhân đôi quà thì nhân đôi người săn quà; tỉ lệ ở lại không đổi.',
      d:'Đổi kênh không giải quyết việc đang thưởng sai hành động.'} },
  { type:'calc', stem:'Chiến dịch tốn 5 tỉ đồng, đem về 100.000 lượt tải; sau 30 ngày còn 4.000 người đặt lịch. Chi phí cho mỗi người dùng còn hoạt động là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:1.25, tol:0.01, wrong:[[0.05,'TINH_TREN_KHACH_KHONG_HOAT_DONG'],[0.125,'SAI_TINH_TOAN']], errors:['TINH_TREN_KHACH_KHONG_HOAT_DONG'],
    steps:['Chia chi phí cho người còn hoạt động, không chia cho lượt tải.','5.000.000.000 ÷ 4.000 = 1.250.000đ = <b>1,25 triệu đồng</b>.'] },
  { type:'mcq', stem:'Nhà đầu tư hỏi con số nào để đánh giá app có "sống" không?',
    options:[{k:'a',t:'Tổng lượt tải cộng dồn kể từ ngày ra mắt tới nay của ứng dụng'},{k:'b',t:'Tỉ lệ người tải còn làm hành động cốt lõi sau 30 và 90 ngày'},
             {k:'c',t:'Xếp hạng của app trên bảng xếp hạng App Store trong tuần'},{k:'d',t:'Số sao đánh giá trung bình của người dùng trên cửa hàng ứng dụng'}],
    answer:'b', why:{a:'Lượt tải cộng dồn chỉ tăng, không bao giờ giảm, nên không phản ánh sức sống.',
      b:'Đúng. Giữ chân theo thời gian cho biết app có tạo được thói quen không.',
      c:'Xếp hạng phản ánh tốc độ tải trong tuần, có thể mua được bằng quà.',
      d:'Số sao phản ánh cảm nhận của người còn dùng, không cho biết bao nhiêu người còn dùng.'} },
  { type:'mcq', stem:'App giao đồ ăn A có MAU 200.000, app B có MAU 150.000. B có số đơn trung bình mỗi người dùng mỗi tháng gấp đôi A. Nhận định nào hợp lý nhất?',
    options:[{k:'a',t:'A mạnh hơn vì có nhiều người dùng hoạt động hằng tháng hơn'},{k:'b',t:'Hai app ngang nhau vì MAU chênh nhau không đáng kể lắm'},
             {k:'c',t:'B có thể mạnh hơn: tổng số đơn của B nhiều hơn A khoảng 50%'},{k:'d',t:'A tốt hơn vì người dùng ít đặt thì chi phí phục vụ sẽ thấp hơn'}],
    answer:'c', why:{a:'MAU chỉ đếm người có hoạt động, không đếm họ dùng sâu tới đâu.',
      b:'MAU chênh 25%, nhưng số đơn chênh theo hướng ngược lại.',
      c:'Đúng. Nếu A là x đơn/người, B là 2x: 150.000 × 2x = 300.000x so với 200.000x.',
      d:'Chi phí phục vụ thấp không bù được việc ít đơn hơn.'} },
  { type:'mcq', stem:'Với app đặt lịch cắt tóc, "người dùng hoạt động" nên được định nghĩa thế nào?',
    options:[{k:'a',t:'Người mở app ít nhất một lần trong 30 ngày qua'},{k:'b',t:'Người đã tạo tài khoản và điền đủ số điện thoại'},
             {k:'c',t:'Người bật thông báo đẩy của app trên điện thoại'},{k:'d',t:'Người có lịch hẹn hoàn thành trong 30 ngày qua'}],
    answer:'d', why:{a:'Mở app có thể chỉ vì bấm nhầm thông báo; không phải giá trị cốt lõi.',
      b:'Tạo tài khoản là bước đầu, không cho biết họ có dùng dịch vụ.',
      c:'Bật thông báo không phải là dùng dịch vụ.',
      d:'Đúng. Lịch hẹn hoàn thành là lúc app tạo ra giá trị cho khách và cho tiệm.'} },
  { type:'mcq', stem:'Một game mobile có 1 triệu lượt tải nhưng DAU (người chơi mỗi ngày) chỉ 5.000. Việc nên làm trước tiên là gì?',
    options:[{k:'a',t:'Tìm xem người chơi rời game ở màn nào, sửa trải nghiệm đó'},{k:'b',t:'Mua thêm quảng cáo để kéo 1 triệu lượt tải tiếp theo cho game'},
             {k:'c',t:'Đổi biểu tượng và ảnh chụp màn hình để tăng tỉ lệ cài đặt'},{k:'d',t:'Gửi thông báo đẩy mỗi ngày cho cả 1 triệu người đã tải game về'}],
    answer:'a', why:{a:'Đúng. Vấn đề là giữ chân; phải tìm điểm người chơi bỏ đi.',
      b:'Kéo thêm người vào thùng thủng thì lại chảy ra hết.',
      c:'Tăng tỉ lệ cài chỉ làm lượt tải đẹp hơn.',
      d:'Spam thông báo khiến nhiều người xoá game hẳn.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:dl08-04', skill:'measure', read:'7 phút', t:'Team marketing mang về 800 lead, sao sales vẫn kêu thiếu khách?',
  situation:'Một trung tâm tiếng Anh ở Hà Nội chạy form đăng ký "nhận tài liệu IELTS miễn phí". Tháng này marketing mang về 800 lead, gấp đôi tháng trước. Đội tư vấn gọi hết danh sách và phàn nàn: nhiều số không nghe máy, nhiều người là học sinh lớp 6 chỉ muốn tài liệu. Số học viên đăng ký khoá học vẫn là 16, như tháng trước.',
  concept:{ name:'Lead và lead đủ điều kiện',
    body:'Lead là người để lại thông tin. <b>Lead đủ điều kiện</b> là lead khớp với một bộ tiêu chí đã thống nhất giữa marketing và sales: đúng độ tuổi, đúng nhu cầu, có khả năng chi trả, sẵn sàng nói chuyện trong thời gian gần. Khi marketing được chấm bằng số lead, họ sẽ chọn mồi dễ nhất (tài liệu miễn phí) và kéo cả những người không bao giờ mua. Chỉ số ra quyết định là <b>số lead đủ điều kiện</b> và <b>chi phí mỗi học viên đăng ký</b>.' },
  example:'Tháng trước: 400 lead, 60 đủ điều kiện, 16 học viên. Tháng này: 800 lead, 64 đủ điều kiện, 16 học viên. Chi quảng cáo tăng từ 20 lên 40 triệu. Chi phí mỗi học viên từ 1,25 triệu lên 2,5 triệu. Trung tâm thêm hai câu hỏi vào form (năm sinh, mục tiêu điểm) và chỉ tính lead đủ điều kiện là người từ 16 tuổi, mục tiêu từ 6.0. Số lead rơi xuống 300, nhưng lead đủ điều kiện lên 90.',
  takeaway:'Lead là số người để lại số điện thoại; lead đủ điều kiện là số người có thể mua.',
  apply:'Ngồi với sales 30 phút, cùng viết ra 3 tiêu chí để một lead được tính là đủ điều kiện.',
  mistakes:['Đặt KPI cho marketing bằng tổng số lead.','Làm form càng ngắn càng tốt để lead rẻ, bất kể chất lượng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: số lead tăng gấp đôi nhờ tặng tài liệu miễn phí. Số học viên đăng ký nhiều khả năng ra sao?',
    options:[{k:'a',t:'Tăng gấp đôi theo lead, vì tỉ lệ chốt của đội tư vấn không đổi'},{k:'b',t:'Gần như không đổi, vì lead thêm vào chủ yếu là người không mua'},
             {k:'c',t:'Tăng gấp ba, vì nhiều lead thì tư vấn có nhiều lựa chọn hơn'},{k:'d',t:'Giảm mạnh, vì học sinh lớp 6 sẽ phàn nàn làm hỏng tiếng tăm'}],
    answer:'b', why:{a:'Tỉ lệ chốt giữ nguyên chỉ khi lead mới giống lead cũ; mồi tài liệu kéo người khác hẳn.',
      b:'Đúng. Mồi dễ kéo thêm người để lại số, không kéo thêm người muốn học.',
      c:'Nhiều lead kém còn làm tư vấn mất thời gian cho lead tốt.',
      d:'Không có cơ chế làm đăng ký giảm mạnh; vấn đề là không tăng.'} },
  { type:'mcq', stem:'Giám đốc muốn giữ KPI "1.000 lead mỗi tháng". Bạn đề xuất sửa gì?',
    options:[{k:'a',t:'Giữ KPI 1.000 lead nhưng thưởng thêm cho đội sales nếu chốt được nhiều hơn'},{k:'b',t:'Bỏ hẳn form và chỉ nhận khách tự đến trung tâm hỏi trực tiếp'},
             {k:'c',t:'Đổi KPI sang số lead đủ điều kiện theo tiêu chí thống nhất với sales'},{k:'d',t:'Thuê thêm tư vấn viên để gọi hết 1.000 lead nhanh hơn trong ngày'}],
    answer:'c', why:{a:'Thưởng sales không sửa được việc marketing đang tối ưu sai số.',
      b:'Bỏ form là bỏ cả nguồn lead tốt.',
      c:'Đúng. Khi marketing và sales cùng đo lead đủ điều kiện, cả hai kéo cùng một hướng.',
      d:'Gọi nhanh hơn một danh sách kém thì vẫn chỉ ra 16 học viên.'} },
  { type:'calc', stem:'Tháng này chi 40 triệu đồng quảng cáo, được 800 lead và 16 học viên đăng ký. Chi phí mỗi học viên là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:2.5, tol:0.01, wrong:[[0.05,'SAI_MAU_SO'],[1.25,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Chi phí mỗi học viên = chi quảng cáo ÷ số học viên (không phải ÷ số lead).','40 ÷ 16 = <b>2,5 triệu đồng</b>.'] },
  { type:'mcq', stem:'Thêm hai câu hỏi vào form làm lead giảm từ 800 xuống 300, nhưng lead đủ điều kiện tăng từ 64 lên 90. Nên đọc thế nào?',
    options:[{k:'a',t:'Chiến dịch tệ đi vì lead giảm hơn 60%, nên bỏ hai câu hỏi đi'},{k:'b',t:'Chưa kết luận được vì lead giảm và lead tốt tăng cùng một lúc'},
             {k:'c',t:'Cần quay về form cũ để có đủ lead cho đội tư vấn gọi mỗi ngày'},{k:'d',t:'Chiến dịch tốt lên: form lọc bớt người không mua và giữ người mua'}],
    answer:'d', why:{a:'Lead giảm là do lọc bỏ người không mua; đó là mục đích.',
      b:'Kết luận được, vì thước đo ra quyết định là lead đủ điều kiện, và nó tăng.',
      c:'Tư vấn bận với lead kém là chính vấn đề cần sửa.',
      d:'Đúng. Ít lead hơn nhưng nhiều lead tốt hơn, và tư vấn dành thời gian đúng chỗ.'} },
  { type:'mcq', stem:'Công ty phần mềm kế toán chạy webinar được 500 người đăng ký. Tiêu chí nào hợp lý nhất để tính lead đủ điều kiện?',
    options:[{k:'a',t:'Người xem webinar hơn 30 phút và điền đầy đủ họ tên cá nhân'},{k:'b',t:'Là kế toán hoặc chủ doanh nghiệp, công ty đủ quy mô, cần phần mềm trong 6 tháng'},
             {k:'c',t:'Người bấm thích bài đăng quảng bá webinar trên fanpage công ty'},{k:'d',t:'Người mở email nhắc lịch webinar ít nhất hai lần trong tuần trước buổi phát sóng'}],
    answer:'b', why:{a:'Xem lâu là tín hiệu quan tâm, nhưng sinh viên kế toán cũng xem lâu.',
      b:'Đúng. Tiêu chí gắn với vai trò, quy mô và thời điểm mua là thứ sales cần.',
      c:'Thích bài đăng còn xa hơn cả đăng ký.',
      d:'Mở email không cho biết họ có quyền quyết định mua.'} },
  { type:'mcq', stem:'Agency báo "chi phí mỗi lead chỉ 25.000đ, giảm một nửa". Câu hỏi nào nên đặt lại cho agency?',
    options:[{k:'a',t:'Có thể giảm tiếp xuống 15.000đ mỗi lead trong tháng sau bằng cách đổi mồi khác không'},{k:'b',t:'Chi phí lead của đối thủ trong ngành đang ở mức bao nhiêu'},
             {k:'c',t:'Làm sao để tăng thêm số lead mà vẫn giữ được mức giá này'},{k:'d',t:'Bao nhiêu lead trong đó đủ điều kiện, chi phí mỗi học viên là bao nhiêu'}],
    answer:'d', why:{a:'Ép giá lead càng đẩy agency tìm mồi rẻ hơn, lead kém hơn.',
      b:'So giá lead với đối thủ vẫn là so trên thước đo sai.',
      c:'Tăng lead rẻ mà không biết chất lượng thì vẫn là đổ tiền vào số phù phiếm.',
      d:'Đúng. Lead rẻ chỉ có nghĩa khi chi phí mỗi khách mua cũng giảm.'} },
  { type:'mcq', stem:'Tiêu chí lead đủ điều kiện nên do ai quyết định?',
    options:[{k:'a',t:'Marketing và sales cùng thống nhất, xem lại sau vài tháng'},{k:'b',t:'Chỉ marketing, vì họ là người chạy quảng cáo ra lead'},
             {k:'c',t:'Chỉ sales, vì họ là người trực tiếp gọi điện và chốt khách'},{k:'d',t:'Agency, vì họ có dữ liệu của nhiều khách hàng khác'}],
    answer:'a', why:{a:'Đúng. Tiêu chí cần cả hai phía đồng ý, và cần sửa khi dữ liệu chốt khách cho thấy lệch.',
      b:'Marketing tự đặt thì dễ đặt tiêu chí dễ đạt.',
      c:'Sales tự đặt thì marketing không hiểu vì sao lead bị loại.',
      d:'Agency không biết khách của bạn chốt được hay không.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:dl08-05', skill:'measure', read:'7 phút', t:'Doanh thu Tết tăng 40%, sao cuối quý lại lỗ?',
  situation:'Một shop hạt dinh dưỡng bán trên Shopee chạy khuyến mãi Tết giảm 25% cho mọi hộp quà, kèm freeship. Doanh thu tháng Chạp tăng 40% so với tháng trước, chủ shop khoe trong nhóm bạn kinh doanh. Nhưng khi kế toán tính xong phí sàn, phí vận chuyển và tiền quảng cáo, tháng đó shop lỗ gần 20 triệu.',
  concept:{ name:'Doanh thu và lãi gộp sau chi phí marketing',
    body:'Doanh thu là tổng tiền khách trả. Nó tăng khi bạn giảm giá mạnh, dù mỗi đơn đem về ít tiền hơn hoặc lỗ. Chỉ số ra quyết định là <b>lãi sau chi phí biến đổi và chi phí marketing</b>: doanh thu trừ giá vốn, phí sàn, vận chuyển, quà tặng, quảng cáo. Nhìn doanh thu, bạn sẽ muốn giảm giá thêm. Nhìn lãi, bạn sẽ hỏi: đợt giảm giá này có kéo thêm đủ đơn để bù phần lãi mất đi trên mỗi đơn không?' },
  example:'Hộp quà giá 400.000đ, giá vốn 200.000đ, phí sàn và vận chuyển 60.000đ. Bình thường lãi 140.000đ/hộp. Giảm 25% còn 300.000đ, lãi còn 40.000đ/hộp. Muốn giữ tổng lãi như cũ, shop cần bán gấp 3,5 lần số hộp. Doanh thu tăng 40% nghĩa là số hộp chỉ tăng khoảng 87%. Tết sau, shop giảm 10% và tặng thiệp viết tay, đo bằng lãi mỗi tuần.',
  takeaway:'Doanh thu cho biết bạn bận đến đâu; lãi cho biết bạn có nên bận như vậy không.',
  apply:'Lấy đợt khuyến mãi gần nhất, tính lãi mỗi đơn trước và trong khuyến mãi, rồi tính số đơn cần để hoà.',
  mistakes:['Quên trừ phí sàn và vận chuyển khi tính lãi khuyến mãi.','Coi doanh thu tăng là bằng chứng khuyến mãi thành công.'],
  q:[
  { type:'mcq', stem:'Đoán trước: giảm giá 25% cho một sản phẩm có lãi 35% trên giá bán. Để giữ tổng lãi, số đơn cần tăng khoảng bao nhiêu?',
    options:[{k:'a',t:'Tăng khoảng 25%, bằng đúng mức giảm giá đã áp dụng'},{k:'b',t:'Tăng khoảng 35%, bằng tỉ lệ lãi trên giá bán ban đầu'},
             {k:'c',t:'Tăng nhiều lần, vì phần giảm giá ăn gần hết lãi mỗi đơn'},{k:'d',t:'Chỉ cần tăng nhẹ vì freeship và quà đã kéo khách về rồi'}],
    answer:'c', why:{a:'Giảm 25% giá bán trừ thẳng vào lãi, không phải vào doanh thu tỉ lệ thuận.',
      b:'Con số lãi 35% dùng để tính, nhưng kết quả không phải 35%.',
      c:'Đúng. Lãi từ 35% giá còn 10% giá bán cũ; cần khoảng 3,5 lần số đơn.',
      d:'Freeship còn làm lãi mỗi đơn mỏng thêm, không phải bù lại.'} },
  { type:'mcq', stem:'Chủ shop định chạy tiếp khuyến mãi 25% cho tháng Giêng vì "doanh thu đẹp". Bạn đề xuất gì?',
    options:[{k:'a',t:'Chạy tiếp vì doanh thu tăng giúp shop lên hạng trên sàn'},{k:'b',t:'Tính số đơn cần để hoà vốn; nếu không đạt thì giảm mức giảm giá'},
             {k:'c',t:'Tăng mức giảm lên 35% để doanh thu tăng hơn nữa cho kịp Tết'},{k:'d',t:'Dừng mọi khuyến mãi vĩnh viễn, chỉ bán nguyên giá quanh năm'}],
    answer:'b', why:{a:'Lên hạng mà mỗi đơn lỗ thì càng bán càng lỗ.',
      b:'Đúng. Quyết định dựa trên lãi và điểm hoà, không dựa trên doanh thu.',
      c:'Giảm sâu hơn thì lãi mỗi đơn âm.',
      d:'Khuyến mãi có thể có lãi nếu mức giảm hợp lý; bỏ hẳn là cực đoan.'} },
  { type:'calc', stem:'Hộp quà giá 400.000đ, giá vốn 200.000đ, phí sàn và vận chuyển 60.000đ. Giảm giá 25%, lãi mỗi hộp còn bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:40, tol:0.1, wrong:[[100,'QUEN_CHI_PHI_BIEN_DOI'],[105,'GIAM_GIA_QUEN_BIEN']], errors:['QUEN_CHI_PHI_BIEN_DOI'],
    steps:['Giá sau giảm: 400 × 75% = 300 nghìn đồng.','Lãi = 300 − 200 (giá vốn) − 60 (phí sàn, vận chuyển) = <b>40 nghìn đồng</b>.'] },
  { type:'mcq', stem:'Hai kênh quảng cáo: kênh X đem 200 triệu doanh thu, kênh Y đem 120 triệu. Chi phí và biên lãi khác nhau. Để chọn kênh tăng ngân sách, bạn cần thêm gì?',
    options:[{k:'a',t:'Không cần gì thêm, cứ chọn X vì doanh thu cao hơn gần gấp đôi'},{k:'b',t:'Số đơn mỗi kênh, vì nhiều đơn hơn thì thương hiệu được biết nhiều hơn'},
             {k:'c',t:'Tỉ lệ nhấp mỗi kênh, vì nhấp cao thì kênh đó hợp với sản phẩm hơn'},{k:'d',t:'Lãi sau chi phí quảng cáo và chi phí biến đổi của từng kênh'}],
    answer:'d', why:{a:'Doanh thu cao có thể đến từ bán hàng giảm sâu hoặc quảng cáo đắt.',
      b:'Số đơn vẫn là doanh thu dưới dạng khác.',
      c:'Nhấp là bước giữa, không cho biết tiền còn lại.',
      d:'Đúng. Kênh nào để lại nhiều tiền hơn sau mọi chi phí mới đáng thêm ngân sách.'} },
  { type:'mcq', stem:'Một quán trà sữa đặt KPI cho quản lý chi nhánh bằng doanh thu. Hậu quả dễ thấy nhất là gì?',
    options:[{k:'a',t:'Quản lý tặng topping, giảm giá thoải mái để kéo doanh thu, lãi mỏng đi'},{k:'b',t:'Quản lý chăm sóc khách tốt hơn vì doanh thu phụ thuộc vào khách'},
             {k:'c',t:'Quản lý tiết kiệm nguyên liệu hơn để có tiền đầu tư quảng cáo'},{k:'d',t:'Chi nhánh sẽ tự động có lãi cao hơn vì bán được nhiều ly hơn'}],
    answer:'a', why:{a:'Đúng. Ai được chấm bằng doanh thu sẽ đổi lãi lấy doanh thu.',
      b:'Có thể, nhưng cách dễ nhất để đẩy doanh thu là giảm giá.',
      c:'KPI doanh thu không thưởng cho việc tiết kiệm.',
      d:'Bán nhiều ly giá rẻ không tự động có lãi hơn.'} },
  { type:'mcq', stem:'Doanh thu tháng này giảm 10% nhưng lãi tăng 15%. Tình huống nào giải thích hợp lý?',
    options:[{k:'a',t:'Kế toán tính sai, vì doanh thu giảm thì lãi không thể tăng được'},{k:'b',t:'Khách hàng mua ít đi nên shop đỡ phải trả phí vận chuyển nữa'},
             {k:'c',t:'Shop bỏ bớt khuyến mãi lỗ và kênh quảng cáo đắt, giữ đơn có lãi'},{k:'d',t:'Tháng này ít ngày hơn nên chi phí cố định của shop thấp hơn'}],
    answer:'c', why:{a:'Doanh thu và lãi hoàn toàn có thể đi ngược chiều.',
      b:'Phí vận chuyển giảm theo đơn, nhưng lãi tăng 15% cần lý do lớn hơn.',
      c:'Đúng. Cắt các đơn lỗ làm doanh thu giảm nhưng lãi tăng.',
      d:'Chênh vài ngày không giải thích được lãi tăng 15%.'} },
  { type:'mcq', stem:'Bạn chuẩn bị báo cáo khuyến mãi Tết cho chủ shop. Con số nào đặt ở dòng đầu?',
    options:[{k:'a',t:'Doanh thu tăng 40% so với tháng trước đó của shop'},{k:'b',t:'Lãi sau mọi chi phí, so với tháng không khuyến mãi'},
             {k:'c',t:'Số đơn hàng tăng 87% và thứ hạng của shop trên sàn'},{k:'d',t:'Số khách mới mua lần đầu trong đợt khuyến mãi Tết'}],
    answer:'b', why:{a:'Doanh thu là con số làm vui, không trả lời đợt khuyến mãi có đáng không.',
      b:'Đúng. Lãi so với tháng không khuyến mãi cho biết đợt này thêm hay bớt tiền.',
      c:'Số đơn và thứ hạng vẫn là hoạt động, không phải kết quả tài chính.',
      d:'Khách mới quan trọng, nhưng cần đi kèm lãi và khả năng họ quay lại.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:dl08-06', skill:'measure', read:'6 phút', t:'Email có tỉ lệ mở 45%, sao không ai đặt hàng?',
  situation:'Một chuỗi mỹ phẩm gửi email mỗi tuần cho 40.000 khách. Người phụ trách email được khen vì tỉ lệ mở tăng từ 20% lên 45% sau khi đổi tiêu đề sang kiểu "Bạn có một món quà đang chờ 🎁". Nhưng doanh thu từ email tháng này chỉ 12 triệu, thấp hơn tháng trước (30 triệu). Sếp hỏi: tiêu đề mới tốt hay xấu?',
  concept:{ name:'Tỉ lệ mở và doanh thu từ email',
    body:'Tỉ lệ mở đo tiêu đề có khiến người ta bấm vào không. Nó dễ bị đẩy lên bằng tiêu đề gây tò mò hoặc hứa hẹn quá lời. Ngoài ra, một số ứng dụng email tự tải nội dung trước, khiến số "mở" bị thổi phồng. Chỉ số ra quyết định là <b>doanh thu trên mỗi email gửi đi</b>: doanh thu từ email chia cho số email gửi. Nó gộp cả tiêu đề, nội dung, ưu đãi và trang đích vào một con số gắn với tiền. Tiêu đề hứa quà mà bên trong không có quà thì mở nhiều, mua ít, và còn làm khách mất tin.' },
  example:'Tháng trước: 40.000 email × 4 lần = 160.000 email, doanh thu 30 triệu, tức 187,5đ mỗi email. Tháng này: cùng 160.000 email, doanh thu 12 triệu, tức 75đ mỗi email. Tỉ lệ mở tăng hơn gấp đôi, nhưng mỗi email đem về ít tiền hơn 60%. Chuỗi quay lại tiêu đề nói rõ ưu đãi và theo dõi doanh thu mỗi email hằng tuần.',
  takeaway:'Tỉ lệ mở đo tiêu đề; doanh thu mỗi email đo cả lá thư.',
  apply:'Lấy 4 email gần nhất, chia doanh thu của mỗi email cho số người nhận, xếp hạng lại và so với xếp hạng theo tỉ lệ mở.',
  mistakes:['Viết tiêu đề giật gân để tăng tỉ lệ mở.','Tin tuyệt đối vào tỉ lệ mở dù nhiều ứng dụng email tự mở trước.'],
  q:[
  { type:'mcq', stem:'Đoán trước: tiêu đề "Bạn có một món quà đang chờ" làm tỉ lệ mở tăng gấp đôi, nhưng bên trong chỉ là tin sản phẩm mới. Doanh thu từ email nhiều khả năng ra sao?',
    options:[{k:'a',t:'Tăng gấp đôi theo tỉ lệ mở, vì có gấp đôi người đọc thư hơn'},{k:'b',t:'Tăng nhẹ vì có thêm người đọc, dù thư không có quà thật'},
             {k:'c',t:'Tăng mạnh sau vài tuần khi khách đã quen với tiêu đề mới'},{k:'d',t:'Có thể giảm, vì khách mở ra thấy bị hứa suông và mất tin'}],
    answer:'d', why:{a:'Người mở vì tò mò khác người mở vì muốn mua.',
      b:'Có thể tăng nhẹ nếu thư tốt, nhưng hứa suông thường làm khách phật ý.',
      c:'Khách quen với tiêu đề hứa suông thì càng ít tin, không phải mua nhiều hơn.',
      d:'Đúng. Hứa quà mà không có quà làm giảm lòng tin và giảm mua.'} },
  { type:'mcq', stem:'Sếp hỏi nên giữ tiêu đề mới hay quay lại. Bạn chọn cách đánh giá nào?',
    options:[{k:'a',t:'Giữ tiêu đề mới vì tỉ lệ mở cao cho thấy khách thích thư hơn'},{k:'b',t:'So doanh thu trên mỗi email gửi giữa hai kiểu tiêu đề trên cùng tệp'},
             {k:'c',t:'Hỏi ý kiến đội thiết kế xem tiêu đề nào trông hấp dẫn hơn'},{k:'d',t:'Dùng tiêu đề nào có tỉ lệ nhấp vào đường link cao hơn trong thư, vì nhấp gần với mua hơn'}],
    answer:'b', why:{a:'Mở nhiều không có nghĩa là thích thư hay mua.',
      b:'Đúng. Doanh thu mỗi email gửi đi là thước đo gắn với tiền và so được giữa hai kiểu.',
      c:'Cảm nhận của đội thiết kế không thay được dữ liệu mua hàng.',
      d:'Nhấp gần hơn mở, nhưng vẫn chưa phải mua; tiêu đề giật gân cũng kéo nhấp tò mò.'} },
  { type:'calc', stem:'Tháng này gửi 160.000 email, doanh thu từ email là 12 triệu đồng. Doanh thu trên mỗi email gửi đi là bao nhiêu đồng?',
    unit:'đồng', ans:75, tol:0.5, wrong:[[166.7,'SAI_MAU_SO'],[300,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Doanh thu mỗi email = doanh thu từ email ÷ số email gửi đi.','12.000.000 ÷ 160.000 = <b>75 đồng</b>.'] },
  { type:'mcq', stem:'Vì sao tỉ lệ mở ngày càng kém tin cậy để so sánh các chiến dịch email?',
    options:[{k:'a',t:'Một số ứng dụng email tự tải nội dung, khiến thư bị tính là đã mở'},{k:'b',t:'Người dùng đọc email trên điện thoại nhiều hơn trên máy tính bàn'},
             {k:'c',t:'Các nhà cung cấp email tính phí theo số lượt mở của từng thư'},{k:'d',t:'Khách hàng ngày nay không còn đọc email từ các thương hiệu nữa'}],
    answer:'a', why:{a:'Đúng. Tính năng bảo vệ quyền riêng tư tự tải thư làm tỉ lệ mở bị thổi phồng.',
      b:'Thiết bị thay đổi không làm số mở sai lệch.',
      c:'Phí thường tính theo số liên hệ hoặc số email gửi, không theo lượt mở.',
      d:'Email vẫn có người đọc và mua; vấn đề là cách đếm "mở".'} },
  { type:'mcq', stem:'Email A: tỉ lệ mở 22%, doanh thu 25 triệu. Email B: tỉ lệ mở 40%, doanh thu 10 triệu. Cả hai gửi cùng số người. Bạn học được gì?',
    options:[{k:'a',t:'B tốt hơn vì hấp dẫn gần gấp đôi số người mở thư ra đọc'},{k:'b',t:'Hai email ngang nhau vì mỗi thư mạnh ở một chỉ số khác nhau'},
             {k:'c',t:'Nội dung và ưu đãi của A thuyết phục người mua tốt hơn B'},{k:'d',t:'A may mắn gửi đúng ngày lương nên doanh thu cao hơn B'}],
    answer:'c', why:{a:'Mở nhiều mà mua ít cho thấy tiêu đề hứa nhiều hơn nội dung trả.',
      b:'Hai chỉ số không ngang giá trị; doanh thu mới là mục tiêu.',
      c:'Đúng. Cùng số người nhận, A đem về gấp 2,5 lần tiền.',
      d:'Ngày gửi có thể ảnh hưởng, nhưng không có dữ kiện nào cho thấy điều đó.'} },
  { type:'mcq', stem:'Người phụ trách email được thưởng theo tỉ lệ mở. Điều gì dễ xảy ra nhất?',
    options:[{k:'a',t:'Thư được viết kỹ hơn và khách mua nhiều hơn theo thời gian'},{k:'b',t:'Tiêu đề ngày càng giật gân và nội dung không theo kịp lời hứa'},
             {k:'c',t:'Số người huỷ đăng ký giảm vì thư được chăm chút kỹ lưỡng'},{k:'d',t:'Chi phí gửi email giảm vì mỗi thư được nhiều người đọc hơn'}],
    answer:'b', why:{a:'Thưởng theo mở không thưởng cho nội dung.',
      b:'Đúng. Người ta tối ưu cái được đo: tiêu đề.',
      c:'Tiêu đề giật gân thường làm huỷ đăng ký tăng.',
      d:'Chi phí gửi không phụ thuộc số người đọc.'} },
  { type:'mcq', stem:'Một thương hiệu gửi email chăm sóc sau mua (hướng dẫn dùng sản phẩm), không bán gì. Chỉ số nào hợp lý nhất cho loại email này?',
    options:[{k:'a',t:'Doanh thu trên mỗi email gửi trong vòng 7 ngày sau khi gửi thư'},{k:'b',t:'Tỉ lệ mở thư, vì thư này không có mục tiêu bán hàng trực tiếp nên chỉ cần khách đọc'},
             {k:'c',t:'Tỉ lệ mua lại sau 60 ngày của nhóm nhận thư so với nhóm không nhận'},{k:'d',t:'Số lượt chuyển tiếp thư cho bạn bè của người nhận trong tuần'}],
    answer:'c', why:{a:'Thư chăm sóc không nhằm bán ngay; đo trong 7 ngày là quá sớm.',
      b:'Tỉ lệ mở vẫn không cho biết thư có giúp giữ khách không.',
      c:'Đúng. Mục tiêu là giữ khách; so nhóm nhận và không nhận cho thấy tác động thật.',
      d:'Chuyển tiếp rất hiếm và không phải mục tiêu của thư chăm sóc.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:dl08-07', skill:'measure', read:'7 phút', t:'Khi chỉ số thành mục tiêu, người ta sẽ "chơi" nó thế nào?',
  situation:'Một chuỗi nhà thuốc đặt KPI cho nhân viên: mỗi người phải mời được 80 khách đăng ký thành viên mỗi tháng, ai đạt được thưởng. Ba tháng sau, số thành viên tăng từ 30.000 lên 90.000. Nhưng khi gửi tin nhắn ưu đãi, 40% số điện thoại không liên lạc được, và nhiều thành viên chưa từng mua lần hai.',
  concept:{ name:'Định luật Goodhart',
    body:'Nhà kinh tế Charles Goodhart nêu một ý thường được tóm lại thế này: <b>khi một chỉ số trở thành mục tiêu, nó không còn là chỉ số tốt</b>. Lý do: người bị đo sẽ tìm cách đẩy con số lên bằng đường dễ nhất, và đường dễ nhất thường không phải đường tạo ra giá trị. Để hạn chế, hãy <b>ghép chỉ số với một chỉ số đối trọng</b> khó chơi hơn (số thành viên đi kèm tỉ lệ thành viên mua lại), kiểm tra ngẫu nhiên dữ liệu, và đổi thước đo khi thấy con số tăng mà kết quả kinh doanh không đổi.' },
  example:'Kiểm tra 200 hồ sơ thành viên mới: 80 số không liên lạc được, 50 số trùng người đã có, nhiều người là người nhà nhân viên. Chuỗi đổi KPI: nhân viên được thưởng theo số thành viên mới <b>có giao dịch lần hai trong 60 ngày</b>. Số đăng ký mới giảm từ 20.000 xuống 6.000 mỗi tháng, nhưng số thành viên mua lần hai tăng từ 1.800 lên 2.400.',
  takeaway:'Thứ gì được đo và thưởng sẽ bị chơi; hãy ghép nó với một chỉ số đối trọng.',
  apply:'Chọn một KPI đang dùng, viết ra cách dễ nhất để "chơi" nó, rồi tìm một chỉ số đối trọng chặn cách đó.',
  mistakes:['Thưởng theo một chỉ số đơn lẻ dễ đẩy lên.','Chỉ nhìn con số tổng, không bao giờ kiểm tra mẫu dữ liệu bên dưới.'],
  q:[
  { type:'mcq', stem:'Đoán trước: nhân viên được thưởng theo số khách đăng ký thành viên. Chất lượng danh sách thành viên sau 3 tháng sẽ ra sao?',
    options:[{k:'a',t:'Tốt lên vì nhân viên có động lực trò chuyện với khách nhiều hơn'},{k:'b',t:'Giữ nguyên vì khách nào đăng ký cũng là khách đã đến nhà thuốc'},
             {k:'c',t:'Tốt lên rõ rệt vì danh sách lớn hơn thì dễ gửi ưu đãi trúng'},{k:'d',t:'Kém đi: nhiều số ảo, số trùng, người không bao giờ quay lại'}],
    answer:'d', why:{a:'Có thể trò chuyện nhiều hơn, nhưng động lực chính là đạt con số.',
      b:'Khi có thưởng, nhiều hồ sơ không đến từ khách thật.',
      c:'Danh sách lớn nhiều số ảo thì gửi ưu đãi càng tốn và càng ít trúng.',
      d:'Đúng. Đường dễ nhất để đạt 80 hồ sơ là điền bừa, trùng lặp, nhờ người nhà.'} },
  { type:'mcq', stem:'Bạn được giao sửa KPI cho nhân viên nhà thuốc. Bạn chọn cách nào?',
    options:[{k:'a',t:'Tăng chỉ tiêu lên 120 thành viên mỗi tháng để tạo áp lực thêm'},{k:'b',t:'Bỏ hẳn KPI thành viên, chỉ thưởng theo doanh thu của cửa hàng'},
             {k:'c',t:'Thưởng theo thành viên mới có giao dịch lần hai trong 60 ngày'},{k:'d',t:'Giữ KPI cũ nhưng phạt nặng nhân viên nào bị phát hiện nhập số ảo'}],
    answer:'c', why:{a:'Chỉ tiêu cao hơn càng đẩy thêm số ảo.',
      b:'Doanh thu cửa hàng không cho nhân viên biết việc xây thành viên có tác dụng.',
      c:'Đúng. Giao dịch lần hai rất khó làm giả và gắn với giá trị thật.',
      d:'Phạt thì nhân viên chuyển sang cách chơi khó phát hiện hơn, KPI vẫn sai.'} },
  { type:'calc', stem:'Kiểm tra 200 hồ sơ thành viên mới: 80 số không liên lạc được, 50 số trùng người đã có. Tỉ lệ hồ sơ có vấn đề là bao nhiêu phần trăm?',
    unit:'%', ans:65, tol:0.1, wrong:[[40,'SAI_TINH_TOAN'],[25,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Hồ sơ có vấn đề = 80 + 50 = 130.','130 ÷ 200 = <b>65%</b>.'] },
  { type:'mcq', stem:'Một agency cam kết KPI "chi phí mỗi lượt nhấp dưới 1.000đ". Họ dễ "chơi" KPI này bằng cách nào?',
    options:[{k:'a',t:'Viết lại nội dung quảng cáo để nêu rõ giá và lợi ích sản phẩm'},{k:'b',t:'Chạy quảng cáo ở vị trí rẻ, dễ bấm nhầm, nhắm nhóm ít khả năng mua'},
             {k:'c',t:'Tăng ngân sách chạy vào giờ cao điểm để tiếp cận được nhiều người'},{k:'d',t:'Thu hẹp nhóm đối tượng lại chỉ còn những người đã mua trước đây'}],
    answer:'b', why:{a:'Nêu giá thường làm giảm nhấp tò mò, khó đạt KPI hơn.',
      b:'Đúng. Nhấp rẻ nhất thường là nhấp nhầm hoặc từ người không mua.',
      c:'Giờ cao điểm thường đắt hơn.',
      d:'Nhắm khách cũ thường có giá nhấp cao hơn, không phải cách "chơi".'} },
  { type:'mcq', stem:'Chỉ số đối trọng tốt cho KPI "số bài đăng mỗi tuần" của đội nội dung là gì?',
    options:[{k:'a',t:'Số hình ảnh trong mỗi bài đăng của đội nội dung'},{k:'b',t:'Số bài đăng của đối thủ trong cùng khoảng thời gian'},
             {k:'c',t:'Người xem hết bài, hoặc số khách hỏi mua từ bài đăng'},{k:'d',t:'Tổng số chữ đội nội dung viết ra được trong tuần đó'}],
    answer:'c', why:{a:'Số hình càng dễ chơi hơn.',
      b:'So với đối thủ vẫn là đếm số lượng.',
      c:'Đúng. Chỉ số chất lượng chặn việc đăng nhiều bài vô giá trị.',
      d:'Số chữ là một cách đếm số lượng khác.'} },
  { type:'mcq', stem:'Số thành viên tăng gấp ba nhưng số thành viên mua lần hai gần như không đổi. Đây là dấu hiệu gì?',
    options:[{k:'a',t:'Chỉ số đã bị chơi: con số tăng mà kết quả thật không nhúc nhích'},{k:'b',t:'Thành viên mới cần thêm thời gian, vài tháng nữa sẽ mua lại thôi'},
             {k:'c',t:'Chương trình thành viên thành công vì tệp khách đã lớn gấp ba'},{k:'d',t:'Giá thuốc tăng khiến thành viên mới chưa muốn quay lại mua lần hai'}],
    answer:'a', why:{a:'Đúng. Khoảng cách giữa con số và kết quả là tín hiệu Goodhart kinh điển.',
      b:'Thời gian có thể giúp một chút, nhưng 40% số không liên lạc được thì không bao giờ mua lại.',
      c:'Tệp lớn gấp ba mà không ai mua thêm thì không phải thành công.',
      d:'Không có dữ kiện về giá; mẫu kiểm tra đã chỉ ra nguyên nhân.'} },
  { type:'mcq', stem:'Cách nào giúp phát hiện sớm một chỉ số đang bị chơi?',
    options:[{k:'a',t:'Đặt chỉ tiêu cao hơn mỗi quý để buộc nhân viên cố gắng'},{k:'b',t:'Chỉ xem báo cáo tổng hợp hằng tháng, không đi vào chi tiết'},
             {k:'c',t:'Tin vào báo cáo của người phụ trách vì họ hiểu số nhất'},{k:'d',t:'Lấy mẫu ngẫu nhiên dữ liệu gốc để kiểm tra định kỳ'}],
    answer:'d', why:{a:'Chỉ tiêu cao hơn làm tăng động lực chơi số.',
      b:'Báo cáo tổng che hết các bất thường bên dưới.',
      c:'Người phụ trách là người có lợi khi con số đẹp.',
      d:'Đúng. Soi mẫu dữ liệu gốc là cách rẻ nhất để thấy số ảo, số trùng.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:dl08-08', skill:'measure', read:'7 phút', t:'Tỉ lệ chuyển đổi tăng gấp đôi, sao số đơn lại giảm?',
  situation:'Một shop giày thể thao chạy quảng cáo Facebook. Tháng trước: 10.000 lượt vào trang, tỉ lệ chuyển đổi 1%, được 100 đơn. Tháng này shop thu hẹp đối tượng, tỉ lệ chuyển đổi lên 2%, người phụ trách báo cáo "hiệu quả tăng gấp đôi". Nhưng lượt vào trang chỉ còn 4.000, và số đơn là 80.',
  concept:{ name:'Chỉ số tỉ lệ và số tuyệt đối',
    body:'Tỉ lệ (chuyển đổi, nhấp, mở) cho biết <b>hiệu suất</b>. Số tuyệt đối (số đơn, số tiền lãi) cho biết <b>kết quả</b>. Tỉ lệ có thể tăng vì mẫu số co lại: bạn bỏ đi những người khó chốt, còn lại toàn người dễ chốt, nhưng tổng đơn ít đi. Khi báo cáo, luôn đặt tỉ lệ cạnh số tuyệt đối. Và khi so hai tỉ lệ, hãy nói rõ là thay đổi <b>điểm phần trăm</b> (từ 1% lên 2% là tăng 1 điểm) hay <b>phần trăm tương đối</b> (tăng 100%).' },
  example:'Tháng trước: 10.000 × 1% = 100 đơn. Tháng này: 4.000 × 2% = 80 đơn. Tỉ lệ tăng gấp đôi nhưng đơn giảm 20%. Nếu lãi mỗi đơn là 150.000đ, shop mất 3 triệu đồng lãi. Shop giữ nhóm đối tượng hẹp (người đã xem sản phẩm) nhưng mở thêm một nhóm rộng riêng, và đặt mục tiêu bằng tổng lãi mỗi tháng.',
  takeaway:'Tỉ lệ đẹp không trả lương; hãy luôn đặt nó cạnh số tuyệt đối.',
  apply:'Lấy một báo cáo có tỉ lệ tăng, tìm con số tuyệt đối tương ứng, kiểm tra nó có tăng không.',
  mistakes:['Khen tỉ lệ chuyển đổi tăng mà không nhìn tổng đơn.','Nói "tăng 1%" khi thực ra là tăng 1 điểm phần trăm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: shop thu hẹp đối tượng quảng cáo, tỉ lệ chuyển đổi tăng từ 1% lên 2%. Điều gì có thể xảy ra với số đơn?',
    options:[{k:'a',t:'Chắc chắn tăng gấp đôi, vì hiệu quả chuyển đổi đã tăng gấp đôi'},{k:'b',t:'Có thể giảm, vì lượt vào trang giảm mạnh hơn mức tăng tỉ lệ'},
             {k:'c',t:'Giữ nguyên, vì tỉ lệ và lượt vào trang luôn bù trừ nhau đều'},{k:'d',t:'Tăng nhẹ, vì đối tượng hẹp thì luôn mua nhiều hơn đối tượng rộng'}],
    answer:'b', why:{a:'Số đơn phụ thuộc cả tỉ lệ lẫn lượt vào trang.',
      b:'Đúng. Thu hẹp đối tượng làm mẫu số co lại; đơn có thể giảm dù tỉ lệ tăng.',
      c:'Không có quy luật bù trừ đều nào cả.',
      d:'Đối tượng hẹp chuyển đổi tốt hơn trên mỗi người, nhưng tổng có thể ít hơn.'} },
  { type:'mcq', stem:'Người phụ trách báo "hiệu quả tăng gấp đôi" và xin giữ cách chạy mới. Bạn phản ứng thế nào?',
    options:[{k:'a',t:'Đồng ý vì tỉ lệ chuyển đổi 2% đã vượt mức trung bình của ngành'},{k:'b',t:'Yêu cầu quay lại đối tượng rộng như tháng trước và bỏ nhóm hẹp'},
             {k:'c',t:'Giữ nhóm hẹp, mở thêm nhóm rộng riêng, đặt mục tiêu bằng tổng lãi'},{k:'d',t:'Tăng giá bán để bù lại số đơn bị mất đi trong tháng vừa qua mà không cần đổi quảng cáo'}],
    answer:'c', why:{a:'Vượt mức trung bình về tỉ lệ không bù được việc đơn giảm.',
      b:'Nhóm hẹp chuyển đổi tốt; bỏ nó là bỏ phần hiệu quả.',
      c:'Đúng. Giữ phần hiệu quả, lấy lại độ phủ, và đo bằng con số tuyệt đối.',
      d:'Tăng giá có thể làm đơn giảm thêm; không giải quyết việc đo sai.'} },
  { type:'calc', stem:'Tháng trước 10.000 lượt vào trang, tỉ lệ chuyển đổi 1%. Tháng này 4.000 lượt, tỉ lệ 2%. Lãi mỗi đơn 150.000đ. Tháng này shop mất bao nhiêu triệu đồng lãi so với tháng trước?',
    unit:'triệu đồng', ans:3, tol:0.01, wrong:[[-6,'NHAM_TI_LE_ROI'],[0.2,'NHAM_SO_TUYET_DOI']], errors:['NHAM_SO_TUYET_DOI'],
    steps:['Đơn tháng trước: 10.000 × 1% = 100. Đơn tháng này: 4.000 × 2% = 80.','Mất 20 đơn × 150.000đ = <b>3 triệu đồng</b>.'] },
  { type:'mcq', stem:'Tỉ lệ nhấp tăng từ 2% lên 3%. Cách nói nào chính xác?',
    options:[{k:'a',t:'Tăng 1 điểm phần trăm, tức tăng 50% so với mức ban đầu'},{k:'b',t:'Tăng 1%, vì 3% trừ 2% ra đúng bằng 1% là xong'},
             {k:'c',t:'Tăng 150%, vì 3 chia cho 2 bằng 1,5 lần mức cũ'},{k:'d',t:'Tăng 3%, vì tỉ lệ mới bây giờ đã là 3% rồi mà'}],
    answer:'a', why:{a:'Đúng. Hiệu hai tỉ lệ là điểm phần trăm; so với mức cũ là tăng tương đối 50%.',
      b:'"Tăng 1%" gây nhầm với tăng tương đối 1%.',
      c:'Gấp 1,5 lần là tăng 50%, không phải 150%.',
      d:'3% là mức mới, không phải mức tăng.'} },
  { type:'mcq', stem:'Cửa hàng A có tỉ lệ khách quay lại 60% trên 100 khách. Cửa hàng B có 35% trên 2.000 khách. Nhận định nào đúng nhất?',
    options:[{k:'a',t:'A tốt hơn hẳn vì tỉ lệ quay lại cao gần gấp đôi B'},{k:'b',t:'Hai cửa hàng không so được vì quy mô quá khác nhau'},
             {k:'c',t:'B nên học cách của A để đưa tỉ lệ lên 60% ngay'},{k:'d',t:'B có 700 khách quay lại, A có 60; tỉ lệ A dựa trên mẫu nhỏ'}],
    answer:'d', why:{a:'Tỉ lệ cao trên mẫu nhỏ dễ dao động và không nói về quy mô.',
      b:'So được, miễn là đặt cả tỉ lệ và số tuyệt đối cạnh nhau.',
      c:'Giữ tỉ lệ cao ở 100 khách dễ hơn nhiều so với ở 2.000 khách.',
      d:'Đúng. Đặt số tuyệt đối cạnh tỉ lệ, và nhớ mẫu nhỏ thì tỉ lệ kém ổn định.'} },
  { type:'mcq', stem:'Khi nào tỉ lệ là chỉ số ra quyết định tốt hơn số tuyệt đối?',
    options:[{k:'a',t:'Khi bạn muốn báo cáo trông đẹp hơn trong cuộc họp cuối tháng'},{k:'b',t:'Khi so hai phiên bản trang đích với lượng khách chia đều như nhau'},
             {k:'c',t:'Khi số tuyệt đối đang giảm và bạn cần một con số tích cực hơn'},{k:'d',t:'Khi mẫu số rất nhỏ, dưới 50 người, để kết quả rõ ràng hơn'}],
    answer:'b', why:{a:'Chọn chỉ số theo độ đẹp là đúng cái bẫy cần tránh.',
      b:'Đúng. Khi mẫu số được giữ bằng nhau, tỉ lệ so trực tiếp được hiệu suất.',
      c:'Dùng tỉ lệ để che số tuyệt đối giảm là tự lừa mình.',
      d:'Mẫu nhỏ làm tỉ lệ dao động mạnh, càng kém tin cậy.'} },
  { type:'mcq', stem:'Báo cáo ghi: "Tỉ lệ khiếu nại giảm từ 5% xuống 4%". Câu hỏi nào nên hỏi thêm?',
    options:[{k:'a',t:'Tỉ lệ khiếu nại của đối thủ đang ở khoảng mức bao nhiêu phần trăm'},{k:'b',t:'Giảm 1 điểm phần trăm này có nghĩa là giảm bao nhiêu phần trăm'},
             {k:'c',t:'Số đơn và số khiếu nại tuyệt đối của hai kỳ là bao nhiêu'},{k:'d',t:'Đội chăm sóc khách hàng đã được thưởng cho kết quả này chưa'}],
    answer:'c', why:{a:'So đối thủ không cho biết thay đổi của chính bạn đến từ đâu.',
      b:'Câu hỏi này đúng về cách nói nhưng không phát hiện được mẫu số thay đổi.',
      c:'Đúng. Nếu số đơn tăng mạnh, số khiếu nại tuyệt đối có thể vẫn tăng.',
      d:'Chưa hiểu con số thì chưa nên nói tới thưởng.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:dl08-09', skill:'measure', read:'7 phút', t:'Giá trị đơn trung bình 500.000đ, nhưng có bao nhiêu đơn thật sự ở mức đó?',
  situation:'Một shop đồ gia dụng báo cáo giá trị đơn trung bình tháng này là 500.000đ, tăng từ 380.000đ, và định dựa vào đó nâng ngưỡng freeship lên 500.000đ. Khi xem danh sách đơn, bạn thấy có 5 đơn của một khách sỉ, mỗi đơn 12 triệu, còn phần lớn đơn khác chỉ 200.000–300.000đ.',
  concept:{ name:'Trung bình che phân phối lệch',
    body:'Số trung bình cộng bị kéo mạnh bởi vài giá trị rất lớn. Khi dữ liệu lệch (vài đơn khổng lồ, vài khách chi rất nhiều), trung bình không mô tả "khách điển hình". Hãy nhìn thêm <b>trung vị</b> (giá trị ở giữa khi xếp thứ tự), và <b>chia nhóm</b>: khách lẻ và khách sỉ, khách mới và khách cũ. Quyết định nào áp lên khách điển hình (ngưỡng freeship, combo, mức giá) phải dựa trên trung vị hoặc từng nhóm, không dựa trên trung bình chung.' },
  example:'Shop có 200 đơn, tổng 100 triệu: trung bình 500.000đ. Bỏ 5 đơn sỉ (60 triệu), còn 195 đơn lẻ tổng 40 triệu: trung bình khoảng 205.000đ. Trung vị toàn bộ là 240.000đ. Nếu đặt ngưỡng freeship 500.000đ, gần như không khách lẻ nào đạt. Shop đặt ngưỡng 300.000đ, vừa trên trung vị một chút, để khuyến khích khách thêm một món.',
  takeaway:'Trước khi tin số trung bình, hãy xem ai đang kéo nó lên.',
  apply:'Xuất danh sách đơn tháng trước, xếp theo giá trị, tìm trung vị và so với số trung bình.',
  mistakes:['Đặt ngưỡng freeship hay combo theo số trung bình chung.','Gộp khách sỉ và khách lẻ vào cùng một báo cáo.'],
  q:[
  { type:'mcq', stem:'Đoán trước: giá trị đơn trung bình tăng từ 380.000đ lên 500.000đ. Điều gì có thể đã xảy ra?',
    options:[{k:'a',t:'Hầu hết khách đều mua thêm món, nên mỗi đơn lẻ đều lớn hơn'},{k:'b',t:'Shop đã tăng giá bán toàn bộ sản phẩm lên khoảng 30%'},
             {k:'c',t:'Vài đơn rất lớn kéo trung bình lên, khách lẻ không đổi'},{k:'d',t:'Khách chuyển sang mua hàng cao cấp hơn nhờ quảng cáo'}],
    answer:'c', why:{a:'Có thể, nhưng một vài đơn khổng lồ cũng tạo ra đúng con số đó.',
      b:'Không có dấu hiệu tăng giá; cần xem danh sách đơn trước khi đoán.',
      c:'Đúng. Trung bình rất nhạy với giá trị cực lớn.',
      d:'Đây là một khả năng nhưng cần dữ kiện; số trung bình một mình không chứng minh được.'} },
  { type:'mcq', stem:'Shop định nâng ngưỡng freeship lên 500.000đ theo giá trị trung bình. Bạn đề xuất sửa gì?',
    options:[{k:'a',t:'Giữ 500.000đ vì đó là con số trung bình đã được tính cẩn thận rồi'},{k:'b',t:'Tách đơn sỉ ra, đặt ngưỡng theo trung vị đơn lẻ, cao hơn một chút'},
             {k:'c',t:'Bỏ freeship hoàn toàn vì khách sỉ không cần ưu đãi này nữa'},{k:'d',t:'Đặt ngưỡng 1 triệu đồng để khuyến khích khách mua nhiều hơn hẳn'}],
    answer:'b', why:{a:'Trung bình bị đơn sỉ kéo lên; khách lẻ gần như không đạt nổi.',
      b:'Đúng. Ngưỡng hơi trên mức khách điển hình mua mới khuyến khích thêm món.',
      c:'Khách lẻ vẫn cần freeship; bỏ đi có thể làm đơn giảm.',
      d:'Ngưỡng quá xa khiến khách bỏ cuộc thay vì mua thêm.'} },
  { type:'calc', stem:'200 đơn, tổng 100 triệu đồng; trong đó 5 đơn sỉ tổng 60 triệu. Giá trị trung bình của các đơn lẻ còn lại là bao nhiêu nghìn đồng (làm tròn tới đơn vị)?',
    unit:'nghìn đồng', ans:205, tol:1, wrong:[[500,'SAI_MAU_SO'],[200,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Đơn lẻ: 200 − 5 = 195 đơn; tổng 100 − 60 = 40 triệu.','40.000 ÷ 195 ≈ <b>205 nghìn đồng</b>.'] },
  { type:'mcq', stem:'Thời gian đọc trung bình mỗi bài blog là 4 phút. Khi xem kỹ, 70% người đọc rời đi dưới 20 giây, vài người để tab mở cả tiếng. Kết luận nào đúng?',
    options:[{k:'a',t:'Bài viết hấp dẫn vì người đọc ở lại trung bình tới 4 phút'},{k:'b',t:'Bài quá dài nên cần cắt ngắn xuống còn khoảng 4 phút đọc cho vừa với thói quen người xem'},
             {k:'c',t:'Số liệu bị lỗi nên không thể dùng để rút ra kết luận nào'},{k:'d',t:'Đa số người đọc bỏ đi rất nhanh; con số 4 phút bị vài tab mở kéo lên'}],
    answer:'d', why:{a:'Khách điển hình rời đi dưới 20 giây; 4 phút không mô tả họ.',
      b:'Độ dài không phải vấn đề chính khi người ta rời đi từ đầu bài.',
      c:'Số liệu không lỗi, chỉ lệch; đọc theo phân phối là rút ra được.',
      d:'Đúng. Phân phối lệch khiến trung bình mô tả sai trải nghiệm phổ biến.'} },
  { type:'mcq', stem:'Chỉ số nào mô tả "khách điển hình" tốt hơn khi dữ liệu có vài giá trị cực lớn?',
    options:[{k:'a',t:'Trung vị, tức giá trị nằm giữa khi xếp các đơn theo thứ tự'},{k:'b',t:'Giá trị lớn nhất, vì nó cho biết tiềm năng chi tiêu của khách'},
             {k:'c',t:'Tổng giá trị, vì nó phản ánh đủ mọi đơn hàng của cả tháng'},{k:'d',t:'Trung bình cộng, vì nó được tính từ toàn bộ dữ liệu có sẵn'}],
    answer:'a', why:{a:'Đúng. Trung vị không bị vài giá trị cực lớn kéo lệch.',
      b:'Giá trị lớn nhất là ngoại lệ, không phải điển hình.',
      c:'Tổng không mô tả khách nào cả.',
      d:'Chính vì tính từ mọi giá trị nên trung bình bị kéo bởi ngoại lệ.'} },
  { type:'mcq', stem:'Chuỗi spa thấy chi tiêu trung bình mỗi khách mỗi năm là 6 triệu. 10% khách chi hơn 30 triệu, phần lớn chi dưới 2 triệu. Bạn nên làm gì với chương trình chăm sóc khách?',
    options:[{k:'a',t:'Thiết kế một gói chung 6 triệu mỗi năm cho toàn bộ khách của chuỗi'},{k:'b',t:'Chỉ chăm sóc nhóm 10% chi nhiều, bỏ qua hoàn toàn nhóm còn lại'},
             {k:'c',t:'Chia hai nhóm với hai chương trình khác nhau, đo riêng từng nhóm'},{k:'d',t:'Giảm giá đồng loạt 20% để kéo trung bình lên khoảng 7 triệu đồng'}],
    answer:'c', why:{a:'Gói 6 triệu quá đắt với đa số và quá nhỏ với nhóm chi nhiều.',
      b:'Nhóm chi ít vẫn là nguồn để phát triển thành khách chi nhiều.',
      c:'Đúng. Hai nhóm có hành vi khác nhau thì cần cách chăm sóc và thước đo riêng.',
      d:'Giảm giá không làm trung bình tăng, và không giải quyết việc gộp nhóm.'} },
  { type:'mcq', stem:'Một báo cáo ghi "mỗi khách giới thiệu trung bình 1,2 người bạn". Bạn nên hỏi thêm gì?',
    options:[{k:'a',t:'Con số này đã tăng bao nhiêu so với cùng kỳ năm ngoái, để biết chương trình giới thiệu có đang tốt lên không'},{k:'b',t:'Bao nhiêu khách giới thiệu ít nhất một người, và vài khách có giới thiệu rất nhiều không'},
             {k:'c',t:'Người được giới thiệu có mua hàng trong 7 ngày đầu tiên không'},{k:'d',t:'Chi phí thưởng cho mỗi lượt giới thiệu hiện nay là bao nhiêu'}],
    answer:'b', why:{a:'So cùng kỳ vẫn dựa trên trung bình có thể bị lệch.',
      b:'Đúng. Có thể 95% khách không giới thiệu ai và vài người giới thiệu hàng chục.',
      c:'Câu hỏi có ích nhưng không kiểm tra được con số trung bình có đại diện không.',
      d:'Chi phí quan trọng nhưng không trả lời phân phối.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:dl08-10', skill:'measure', read:'6 phút', t:'Chỉ số này tăng hay giảm thì bạn có làm khác đi không?',
  situation:'Một startup đồ ăn healthy ở Hà Nội có dashboard 25 chỉ số: follower, lượt thích, lượt xem trang, thời gian trên trang, số bài đăng, tỉ lệ mở email, số lượt tìm kiếm tên thương hiệu... Mỗi sáng thứ Hai cả nhóm ngồi đọc một tiếng. Người sáng lập hỏi bạn: "Tuần nào mình cũng đọc, nhưng hình như chưa bao giờ đổi quyết định vì nó?"',
  concept:{ name:'Phép thử ra quyết định',
    body:'Với mỗi chỉ số, hỏi: <b>nếu con số này tăng gấp đôi hoặc giảm một nửa, tôi sẽ làm gì khác?</b> Nếu câu trả lời là "không làm gì khác", đó là chỉ số để xem cho biết, không nên nằm trên dashboard chính. Chỉ số ra quyết định có ba đặc điểm: gắn với một hành động cụ thể, có người chịu trách nhiệm, và có ngưỡng báo động đã định trước. Một dashboard tốt thường chỉ cần vài chỉ số như vậy, còn lại để ở trang phụ khi cần tra.' },
  example:'Nhóm áp phép thử cho 25 chỉ số. Chỉ 5 chỉ số qua được: số đơn mới mỗi tuần, tỉ lệ khách mua lại trong 30 ngày, chi phí mỗi khách mới, lãi mỗi đơn, tỉ lệ đơn bị phàn nàn. Mỗi chỉ số có một người phụ trách và một ngưỡng: ví dụ tỉ lệ mua lại dưới 25% thì đổi thực đơn tuần. Buổi họp rút từ 60 xuống 20 phút, và lần đầu tiên sau 3 tháng, nhóm đổi thực đơn vì chỉ số mua lại chạm ngưỡng.',
  takeaway:'Chỉ số nào không làm bạn đổi hành động thì chỉ là trang trí.',
  apply:'Lấy dashboard của bạn, viết cạnh mỗi chỉ số: "Nếu nó giảm một nửa, tôi sẽ ___". Xoá những dòng để trống.',
  mistakes:['Thêm chỉ số vào dashboard vì "biết thêm cũng tốt".','Có chỉ số nhưng không đặt ngưỡng và không có người chịu trách nhiệm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: dashboard có 25 chỉ số, cả nhóm đọc mỗi tuần. Vì sao nhóm hiếm khi đổi quyết định?',
    options:[{k:'a',t:'Vì nhóm chưa đọc đủ kỹ, cần thêm thời gian họp mỗi tuần'},{k:'b',t:'Vì dữ liệu chưa đủ chính xác, cần mua công cụ tốt hơn'},
             {k:'c',t:'Vì 25 chỉ số vẫn còn quá ít để thấy được bức tranh đầy đủ'},{k:'d',t:'Vì phần lớn chỉ số không gắn với hành động hay ngưỡng nào'}],
    answer:'d', why:{a:'Đọc lâu hơn những số không gắn hành động vẫn không ra quyết định.',
      b:'Dữ liệu chính xác mà không gắn hành động vẫn chỉ để xem.',
      c:'Thêm chỉ số làm nhiễu thêm, không phải rõ thêm.',
      d:'Đúng. Không có ngưỡng, không có người phụ trách thì con số chỉ để đọc.'} },
  { type:'mcq', stem:'Người sáng lập nhờ bạn làm lại dashboard. Bạn làm gì đầu tiên?',
    options:[{k:'a',t:'Thêm biểu đồ màu sắc cho dễ nhìn và giữ đủ cả 25 chỉ số'},{k:'b',t:'Chỉ giữ các chỉ số liên quan tới mạng xã hội vì đó là kênh chính'},
             {k:'c',t:'Hỏi với mỗi chỉ số: nếu nó giảm một nửa, ta làm gì khác'},{k:'d',t:'Chuyển toàn bộ sang báo cáo tháng để đỡ mất thời gian họp'}],
    answer:'c', why:{a:'Làm đẹp không làm chỉ số gắn với hành động.',
      b:'Lọc theo kênh không phải lọc theo khả năng ra quyết định.',
      c:'Đúng. Phép thử này tách chỉ số ra quyết định khỏi chỉ số để xem.',
      d:'Đọc thưa hơn không sửa được việc đọc sai thứ.'} },
  { type:'calc', stem:'Buổi họp dashboard rút từ 60 xuống 20 phút mỗi tuần, có 6 người dự. Mỗi tháng (4 tuần) nhóm tiết kiệm được bao nhiêu giờ-người?',
    unit:'giờ', ans:16, tol:0.1, wrong:[[2.67,'SAI_TINH_TOAN'],[4,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Tiết kiệm mỗi buổi: 60 − 20 = 40 phút.','40 phút × 6 người × 4 tuần = 960 phút = <b>16 giờ</b>.'] },
  { type:'mcq', stem:'Chỉ số nào sau đây nhiều khả năng qua được phép thử ra quyết định của startup đồ ăn healthy?',
    options:[{k:'a',t:'Tỉ lệ khách mua lại trong 30 ngày, dưới 25% thì đổi thực đơn'},{k:'b',t:'Tổng lượt thích trên tất cả bài đăng của fanpage trong tuần'},
             {k:'c',t:'Số lượt tìm kiếm tên thương hiệu trên Google theo từng ngày'},{k:'d',t:'Thời gian trung bình người xem ở lại trên trang chủ website'}],
    answer:'a', why:{a:'Đúng. Có ngưỡng rõ và gắn với một hành động cụ thể.',
      b:'Lượt thích tăng hay giảm, nhóm cũng khó biết phải đổi gì.',
      c:'Theo dõi theo tháng có thể hữu ích, nhưng theo ngày khó gắn với quyết định.',
      d:'Thời gian trên trang chủ không cho biết phải sửa gì.'} },
  { type:'mcq', stem:'Một chỉ số qua phép thử nhưng không có ai chịu trách nhiệm theo dõi. Điều gì dễ xảy ra?',
    options:[{k:'a',t:'Chỉ số tự cải thiện vì cả nhóm cùng nhìn thấy nó mỗi tuần'},{k:'b',t:'Chỉ số chạm ngưỡng nhưng không ai hành động vì nghĩ người khác lo'},
             {k:'c',t:'Chỉ số trở thành phù phiếm ngay lập tức và cần xoá khỏi bảng'},{k:'d',t:'Người sáng lập sẽ tự động lo mọi việc liên quan tới chỉ số này'}],
    answer:'b', why:{a:'Nhìn thấy không đồng nghĩa với hành động.',
      b:'Đúng. Việc của tất cả mọi người thường thành việc của không ai.',
      c:'Chỉ số vẫn hữu ích; thiếu là người phụ trách chứ không phải bản thân nó.',
      d:'Người sáng lập có quá nhiều việc để tự lo từng chỉ số.'} },
  { type:'mcq', stem:'"Số lượt tìm kiếm tên thương hiệu" nên được xử lý thế nào trong dashboard mới?',
    options:[{k:'a',t:'Đặt lên đầu dashboard vì nó đo mức độ nhận biết thương hiệu'},{k:'b',t:'Xoá hẳn vì mọi chỉ số về thương hiệu đều là phù phiếm cả'},
             {k:'c',t:'Theo dõi mỗi ngày để phát hiện sớm khi thương hiệu bị giảm nhiệt'},{k:'d',t:'Để ở trang phụ, xem theo quý, dùng khi đánh giá chiến dịch lớn'}],
    answer:'d', why:{a:'Nó hữu ích nhưng hằng tuần nhóm không đổi hành động theo nó.',
      b:'Chỉ số thương hiệu có vai trò khi đánh giá chiến dịch dài hạn.',
      c:'Dao động theo ngày chủ yếu là nhiễu.',
      d:'Đúng. Giữ để tra khi cần, không chiếm chỗ trên bảng ra quyết định hằng tuần.'} },
  { type:'mcq', stem:'Một cửa hàng bán lẻ nhỏ muốn chọn 3 chỉ số theo dõi hằng tuần. Bộ nào hợp lý nhất?',
    options:[{k:'a',t:'Số follower, lượt thích và số bài đăng trên mạng xã hội'},{k:'b',t:'Lượt xem trang, thời gian trên trang và tỉ lệ thoát trang'},
             {k:'c',t:'Số khách mua, giá trị đơn trung vị và lãi gộp mỗi tuần'},{k:'d',t:'Tỉ lệ mở email, tỉ lệ nhấp và số người đăng ký nhận tin'}],
    answer:'c', why:{a:'Cả ba là chỉ số hoạt động mạng xã hội, không gắn với tiền.',
      b:'Ba chỉ số đo hành vi trên web, chưa nói gì về bán hàng.',
      c:'Đúng. Ba chỉ số gắn trực tiếp với kết quả và với các quyết định về giá, combo, khuyến mãi.',
      d:'Các chỉ số email là bước giữa, chưa phải kết quả.'} }
  ] }

] });
